import{_ as t,o,c as a,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const c=JSON.parse('{"title":"💡 The Rullst Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/philosophy.md","filePath":"guide/philosophy.md"}'),r={name:"guide/philosophy.md"};function i(l,e,n,h,u,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="💡-the-rullst-philosophy" tabindex="-1">💡 The Rullst Philosophy <a class="header-anchor" href="#💡-the-rullst-philosophy" aria-label="Permalink to &quot;💡 The Rullst Philosophy&quot;">​</a></h1><p>Unlike other frameworks, Rullst strives to be <strong>simultaneously simple and complete</strong>, with a relentless focus on <strong>security</strong> and <strong>developer experience (DX)</strong>.</p><p>The origins of this philosophy can be traced back to the very creation of the Rust programming language. The story goes that Graydon Hoare, the original creator of Rust, lived in an apartment building with an elevator that kept crashing due to software bugs in its underlying C/C++ code. Frustrated by having to climb the stairs because of memory safety vulnerabilities, he set out to create a language that was incredibly fast, yet guaranteed memory safety by design—so that developers could build things that &quot;just worked&quot; without fear.</p><p>Rullst was forged with this exact mindset. We believe that web development shouldn&#39;t be a constant struggle against the framework, the language, or runtime bugs. Rullst is built for those who want to build with ease and safety, harnessing the raw speed and resource efficiency of Rust.</p><h3 id="our-core-tenets" tabindex="-1">Our Core Tenets <a class="header-anchor" href="#our-core-tenets" aria-label="Permalink to &quot;Our Core Tenets&quot;">​</a></h3><ol><li><p><strong>Simple yet Complete:</strong> We solve the hardest web development problems out-of-the-box securely (routing, auth, ORM, background jobs, hot-reloading), without sacrificing simplicity or completeness. You shouldn&#39;t have to piece together 15 different micro-libraries just to build a secure SaaS.</p></li><li><p><strong>Built for Humans and AIs:</strong> Rullst is architected to be highly legible and free of runtime &quot;magic&quot;. By heavily utilizing static dispatch and compile-time guarantees, the codebase is transparent. This empowers both human developers and AI coding agents to collaborate and build production-ready systems rapidly, even without deep prior framework knowledge.</p></li></ol><p>Rullst is not just a tool; it is a commitment to <strong>Emotional Productivity</strong>. We take care of the boilerplate and the security pitfalls so you can focus entirely on creating value.</p>',7)])])}const g=t(r,[["render",i]]);export{c as __pageData,g as default};
